module.exports = async (args) => {
  const streams = args.variables.ffmpegCommand.streams;
  const audio = streams.filter((s) => s.codec_type === 'audio' && !s.removed);
  const hasNonAacAudio = audio.some((s) => s.codec_name !== 'aac');
  let removedCount = 0;
  if (hasNonAacAudio) {
    audio.forEach((s) => {
      if (s.codec_name === 'aac' && !(s.tags && s.tags.title === 'Night Mode')) {
        s.removed = true;
        removedCount += 1;
        args.jobLog(`Removing old plain AAC audio stream 0:${s.index}\n`);
      }
    });
  } else {
    args.jobLog('No non-AAC audio to fall back on - keeping AAC\n');
  }
  if (removedCount > 0) {
    args.variables.ffmpegCommand.shouldProcess = true;
  }
  return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
};

module.exports = async (args) => {
  const streams = (args.inputFileObj && args.inputFileObj.ffProbeData && args.inputFileObj.ffProbeData.streams) || [];
  const hasDoVi = streams.some((s) => {
    if (s.codec_type !== 'video') return false;
    const tag = s.codec_tag_string || '';
    if (/dvhe|dvav|dav1|dvh1/i.test(tag)) return true;
    const sideData = s.side_data_list || [];
    return sideData.some((sd) => (sd.side_data_type || '').includes('DOVI'));
  });
  return {
    outputFileObj: args.inputFileObj,
    outputNumber: hasDoVi ? 1 : 2,
    variables: args.variables,
  };
};

module.exports = async (args) => {
  const streams = args.variables.ffmpegCommand.streams;

  const isEngAudio = (s) => s.codec_type === 'audio' && !s.removed
    && (!s.tags || !s.tags.language || /eng|und/i.test(s.tags.language));

  const candidates = streams.filter(isEngAudio);
  if (candidates.length === 0) {
    args.jobLog('No English/undefined audio stream found - skipping Night Mode track\n');
    return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
  }

  const source = candidates.reduce((a, b) => ((b.channels || 0) > (a.channels || 0) ? b : a));

  const alreadyHasNightMode = streams.some((s) => s.codec_type === 'audio' && !s.removed
    && s.tags && s.tags.title === 'Night Mode');
  if (alreadyHasNightMode) {
    args.jobLog('Night Mode track already present - skipping\n');
    return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
  }

  const nightMode = JSON.parse(JSON.stringify(source));
  nightMode.index = streams.length;
  nightMode.codec_name = 'aac';
  nightMode.channels = 2;
  nightMode.outputArgs = [
    '-c:{outputIndex}', 'aac',
    '-filter:a:{outputTypeIndex}',
    'pan=stereo|FL=0.6*FC+0.5*FL+0.3*BL+0.2*LFE|FR=0.6*FC+0.5*FR+0.3*BR+0.2*LFE,acompressor=threshold=-20dB:ratio=4:attack=20:release=300:makeup=3,loudnorm=I=-16:TP=-1.5:LRA=6',
    '-b:a:{outputTypeIndex}', '192k',
    '-metadata:s:a:{outputTypeIndex}', 'title=Night Mode',
    '-disposition:a:{outputTypeIndex}', 'default',
  ];

  // Insert immediately before the source stream so Night Mode becomes the first audio track
  const sourceArrayIndex = streams.findIndex((s) => s.index === source.index);
  streams.splice(sourceArrayIndex, 0, nightMode);

  // Clear default disposition on the original track so players default to Night Mode
  source.outputArgs.push('-disposition:a:{outputTypeIndex}', '0');

  args.variables.ffmpegCommand.shouldProcess = true;
  args.jobLog(`Added Night Mode stereo AAC track sourced from stream 0:${source.index}\n`);

  return {
    outputFileObj: args.inputFileObj,
    outputNumber: 1,
    variables: args.variables,
  };
};
